import{_ as a,o,c as t,a2 as i}from"./chunks/framework.x7b91k6X.js";const m=JSON.parse('{"title":"漫画 · 第 9 话 团队协作：规范与 Code Review","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.09-team-collaboration.md","filePath":"comics/EP.09-team-collaboration.md","lastUpdated":1792677465000}'),r={name:"comics/EP.09-team-collaboration.md"};function l(n,e,s,d,c,h){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="漫画-·-第-9-话-团队协作-规范与-code-review" tabindex="-1">漫画 · 第 9 话 团队协作：规范与 Code Review <a class="header-anchor" href="#漫画-·-第-9-话-团队协作-规范与-code-review" aria-label="Permalink to &quot;漫画 · 第 9 话 团队协作：规范与 Code Review&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../09-team-collaboration">09-team-collaboration.md</a> ｜ 原画：<a href="./EP.09-team-collaboration.svg">EP.09-team-collaboration.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>斯威芙蒂</strong>：团队十个人十种代码风格，PR review 只回「LGTM 👍」，bug 照样合进 main。</li><li><strong>Runtime 长老</strong>：教她用工具强制规范、用清单保真 review。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>没有工具约束的规范等于没规范——你写 <code>func doThing(_ x:Int)-&gt;String{</code>，他写 <code>func doThing(_ x: Int) -&gt; String {</code>，review 时没人较真。正确的做法是：SwiftLint 配置进仓库、CI 不过不合并；Code Review 对照五查清单（正确性/可读性/测试/性能/安全）逐项打勾；Git Flow 保证 main 永远可发布。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>两个典型问题：</p><ul><li><strong>风格混乱</strong>：没有强制工具，团队代码风格靠「自觉」，结果一个文件里三种缩进、两种命名。</li><li><strong>Review 走过场</strong>：PR 扔上去没人认真看，回复「LGTM」就合并，bug 混进主干。</li></ul><p>根本原因：<strong>规范没有工具化，review 没有清单化</strong>。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><ul><li><strong>SwiftLint 强制风格</strong>：<code>.swiftlint.yml</code> 配置规则（行长度、命名、强制解包禁用等），提交前本地跑、CI 上跑，不通过不合并。规范当代码管，进仓库全员生效。</li><li><strong>Swift API 设计准则</strong>：命名清晰（<code>remove(at:)</code> 而非 <code>remove(_:)</code>）、协议前置（先定义协议再写实现）、错误显式（用 <code>throws</code> 而非返回 <code>nil</code>/错误码）。</li><li><strong>Git Flow</strong>：feature 分支开发 → PR → 至少 1 人 approve + CI 通过 → squash merge 到 main。main 分支保护，禁止直推。</li><li><strong>模块化</strong>：按业务拆成独立 SPM target 或 Framework，编译隔离、依赖单向（上层依赖下层，下层不能反向依赖上层）。</li></ul><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>Code Review 五查清单：</p><ol><li><strong>查正确性</strong>：边界条件、错误处理、并发安全（Actor/锁）、Optional 处理；</li><li><strong>查可读性</strong>：命名语义清晰、函数单一职责、关键逻辑有注释；</li><li><strong>查测试</strong>：新逻辑有单测、改动不破坏旧测试、不通过 <code>// swiftlint:disable</code> 绕过规则；</li><li><strong>查性能</strong>：避免 O(n²) 循环、主线程不做 IO、图片按需解码；</li><li><strong>查安全</strong>：无强制解包、无硬编码密钥/URL、机密走 Keychain。</li></ol><h2 id="runtime-长老划重点" tabindex="-1">Runtime 长老划重点 <a class="header-anchor" href="#runtime-长老划重点" aria-label="Permalink to &quot;Runtime 长老划重点&quot;">​</a></h2><ol><li>规范靠工具落地：SwiftLint 进 CI，不通过不合并，不靠人盯。</li><li>Code Review 五查：正确性/可读性/测试/性能/安全，对照清单不走过场。</li><li>模块化拆分依赖，feature 分支 + PR 审批，主干永远可发布。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么不推荐在 PR 里同时做「功能开发 + 重构 + 格式化」三件事？</p><p><strong>答</strong>：因为这会让 review 成本爆炸。一个 500 行的 PR 里混了格式化（300 行空白/缩进变动）+ 重构（150 行移动）+ 新功能（50 行），reviewer 很难定位真正的逻辑变更，很容易漏掉 bug。正确做法：格式化单独提一个 PR（只动空白和风格），重构单独提一个 PR（只移动不改逻辑），新功能单独提一个 PR。每个 PR 职责单一，review 快且准。</p><h2 id="去实验室" tabindex="-1">去实验室 <a class="header-anchor" href="#去实验室" aria-label="Permalink to &quot;去实验室&quot;">​</a></h2><p>安装 <code>brew install swiftlint</code>，在项目根目录创建 <code>.swiftlint.yml</code> 并运行 <code>swiftlint lint</code>；阅读第 9 章的 Code Review 检查清单模板和模块化拆分方案。</p><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>团队协作顺了，可金融 App 要合规、医疗 App 要 HIPAA、零售 App 要高并发。第 10 话《企业场景：行业与合规》，看通用工程能力如何映射到具体行业。</p>',25)])])}const g=a(r,[["render",l]]);export{m as __pageData,g as default};
